//! Test-only direct DATA adapter, not a production owner or replacement Tree.
use crate::{captured_raw_file::{self,Config},captured_raw_policy::Configuration,captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_raw_tree_pages::{Data,Policy},captured_ui_actions::{self as ui,UiProc,SignatureFile,C2Sources,Roots},reactive_raw_policy_pages::RawPolicyPages};
use std::{path::{Path,PathBuf},sync::Arc,io};
pub struct Pages{pub root:PathBuf,pub rows:Vec<(String,dm_preprocess::SourceText)>,pub budget:Arc<Budget>,pub visits:std::cell::Cell<usize>,pub stop:Option<usize>}
impl RawPolicyPages for Pages{fn for_each(&self,visit:&mut dyn FnMut(&str,captured_raw_file::RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{let phase=self.visits.get();self.visits.set(phase+1);for(rel,text)in &self.rows{if !captured_raw_file::with_original_policy_file(&self.root,&self.root.join(rel),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(self.stop!=Some(phase))}}
pub struct Direct{pub root:PathBuf,pub rows:Vec<(String,dm_preprocess::SourceText)>,pub names:Vec<SignatureFile>}
impl C2Sources for Direct{
 fn named(&self,name:&str,b:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<Vec<UiProc>,Failure>{let mut out=Vec::new();for f in &self.names{for p in &f.procs{poll()?;if p.proc.name==name{b.charge(p.retained_charge().ok_or("test metadata overflow")?+128).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;out.push(p.clone())}}}Ok(out)}
 fn lines(&self,p:&ui::SourceProc,b:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,visit:&mut dyn FnMut(usize,&str)->Result<bool,Failure>)->Result<(),Failure>{let actual=self.names.iter().flat_map(|f|&f.procs).find(|v|v.proc==*p).ok_or("test current header absent")?;let(_,text)=self.rows.iter().find(|r|r.0==p.rel).ok_or("test current raw source absent")?;captured_raw_file::with_original_policy_file(&self.root,&self.root.join(&p.rel),text.clone(),0,b,&mut|_,views|{ui::with_proc_lines(views,actual,b,poll,visit)?;Ok(true)})?;Ok(())}
}
impl Roots for Direct{fn sources(&mut self,f:Vec<SignatureFile>,_:&Arc<Budget>,_:&dyn Fn()->io::Result<()>)->Result<(),Failure>{self.names=f;Ok(())}fn bad_offset(&mut self,p:&UiProc,param:&str,b:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<Option<usize>,Failure>{ui::first_bad_offset(self,p,param,b,poll)}}
pub fn run(root:&Path,files:&[(&str,String)],limit:usize,stop:Option<usize>,poll:&dyn Fn()->io::Result<()>)->Result<Data,Failure>{let budget=Budget::new(limit).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;let config_text=files.iter().find(|r|r.0=="tools/ci/lint_scopes.toml").map(|r|r.1.as_bytes());let config=Config::capture(config_text.map_or(Configuration::ProvenMissing,Configuration::Captured))?;let mut rows=Vec::new();let dispatcher=files.iter().find(|r|r.0==crate::ui_actions_policy::DISPATCHER).map(|r|r.1.as_str());let dispatcher=dispatcher.map(|text|crate::util::universal_newlines(text.to_owned()));let prepared=crate::ui_actions_policy::prepare_dispatcher(dispatcher.as_deref(),&budget,poll)?;for(rel,text)in files{if Policy::UiActions.selects_path(rel)&&!rel.ends_with(".d.ts")&&!config.policy_path_exempt("ui_actions",crate::ui_actions_policy::metadata().group,rel){rows.push((rel.to_string(),crate::util::universal_newlines(text.to_owned()).into()));}}rows.sort_by(|a,b|a.0.cmp(&b.0));let pages=Pages{root:root.to_path_buf(),rows:rows.clone(),budget:budget.clone(),visits:std::cell::Cell::new(0),stop};let mut roots=Direct{root:root.to_path_buf(),rows,names:Vec::new()};let result=ui::collect(&pages,&prepared,&mut roots,&config,&budget,poll)?;assert_eq!(pages.visits.get(),if prepared.needs_sources(){2}else{0});Ok(result)}
